//! Windows: links the application icon and version information into `bae.exe`.
//!
//! `assets/icons/app/bae.res` is a compiled resource file generated by `cargo xtask icons`
//! (icon group 1). Append VERSIONINFO to a build-local copy so the icon can be
//! regenerated independently and the version always follows Cargo.

use std::path::PathBuf;
use std::{env, fs};

fn main() {
    let manifest = PathBuf::from(env::var_os("CARGO_MANIFEST_DIR").expect("set by cargo"));
    let res = manifest.join("../../assets/icons/app/bae.res");
    println!("cargo:rerun-if-changed={}", res.display());
    let target_os = env::var("CARGO_CFG_TARGET_OS").unwrap_or_default();
    let target_env = env::var("CARGO_CFG_TARGET_ENV").unwrap_or_default();
    if target_os == "macos" {
        println!("cargo:rerun-if-changed=src/shell/mac_panels.m");
        cc::Build::new()
            .file("src/shell/mac_panels.m")
            .flag("-fobjc-arc")
            .compile("bae_mac_panels");
        println!("cargo:rustc-link-lib=framework=UserNotifications");
    }
    if target_os == "windows" && target_env == "msvc" {
        let mut resources = fs::read(&res)
            .unwrap_or_else(|error| panic!("{}: {error}; run `cargo xtask icons`", res.display()));
        let output = PathBuf::from(env::var_os("OUT_DIR").expect("set by cargo")).join("bae.res");
        let [major, minor, patch] = [
            env!("CARGO_PKG_VERSION_MAJOR"),
            env!("CARGO_PKG_VERSION_MINOR"),
            env!("CARGO_PKG_VERSION_PATCH"),
        ]
        .map(|part| {
            part.parse::<u16>()
                .expect("Windows version parts must fit in a WORD")
        });
        append_version(&mut resources, major, minor, patch);
        fs::write(&output, resources).expect("write application resources");
        println!("cargo:rustc-link-arg-bins={}", output.display());
    }
}

fn append_version(resources: &mut Vec<u8>, major: u16, minor: u16, patch: u16) {
    const LANGUAGE: u16 = 0x0409; // English (United States)
    const CODE_PAGE: u16 = 1200; // Unicode
    let version = format!("{major}.{minor}.{patch}.0");
    let ms = u32::from(major) << 16 | u32::from(minor);
    let ls = u32::from(patch) << 16;
    let fixed = [
        0xfeef_04bd, // VS_FIXEDFILEINFO signature
        0x0001_0000, // Structure version
        ms,
        ls, // File version
        ms,
        ls, // Product version
        0x3f,
        0,           // File flags mask and flags
        0x0004_0004, // VOS_NT_WINDOWS32
        1,
        0, // VFT_APP and subtype
        0,
        0, // File date
    ];
    let mut data = Vec::new();
    version_block(&mut data, "VS_VERSION_INFO", 52, 0, |out| {
        for field in fixed {
            out.extend_from_slice(&field.to_le_bytes());
        }
        version_block(out, "StringFileInfo", 0, 1, |out| {
            let table = format!("{LANGUAGE:04x}{CODE_PAGE:04x}");
            version_block(out, &table, 0, 1, |out| {
                for (name, value) in [
                    ("FileDescription", "BAE"),
                    ("FileVersion", version.as_str()),
                    ("LegalCopyright", "Copyright 2026 FELIXDAD"),
                    ("ProductName", "BAE"),
                    ("ProductVersion", version.as_str()),
                ] {
                    let words = u16::try_from(value.encode_utf16().count() + 1).expect("fits");
                    version_block(out, name, words, 1, |out| write_utf16(out, value));
                }
            });
        });
        version_block(out, "VarFileInfo", 0, 1, |out| {
            version_block(out, "Translation", 4, 0, |out| {
                out.extend_from_slice(&LANGUAGE.to_le_bytes());
                out.extend_from_slice(&CODE_PAGE.to_le_bytes());
            });
        });
    });

    // RESOURCEHEADER with ordinal type RT_VERSION (16) and name (1).
    align_dword(resources);
    resources.extend_from_slice(&u32::try_from(data.len()).expect("fits").to_le_bytes());
    resources.extend_from_slice(&32u32.to_le_bytes()); // Header size
    for word in [0xffffu16, 16, 0xffff, 1] {
        resources.extend_from_slice(&word.to_le_bytes());
    }
    resources.extend_from_slice(&0u32.to_le_bytes()); // Data version
    resources.extend_from_slice(&0x1030u16.to_le_bytes()); // Memory flags
    resources.extend_from_slice(&LANGUAGE.to_le_bytes());
    resources.extend_from_slice(&[0; 8]); // Version, characteristics
    resources.extend_from_slice(&data);
    align_dword(resources);
}

/// Version blocks share a header. Value length is in UTF-16 words for text and bytes
/// for binary data. Padding before a sibling is outside the preceding block's length.
fn version_block(
    out: &mut Vec<u8>,
    key: &str,
    value_length: u16,
    value_type: u16,
    contents: impl FnOnce(&mut Vec<u8>),
) {
    align_dword(out);
    let start = out.len();
    out.extend_from_slice(&[0; 2]); // Patched with block length below.
    out.extend_from_slice(&value_length.to_le_bytes());
    out.extend_from_slice(&value_type.to_le_bytes());
    write_utf16(out, key);
    align_dword(out);
    contents(out);
    let length = u16::try_from(out.len() - start).expect("fits");
    out[start..start + 2].copy_from_slice(&length.to_le_bytes());
}

fn write_utf16(out: &mut Vec<u8>, text: &str) {
    for word in text.encode_utf16().chain([0]) {
        out.extend_from_slice(&word.to_le_bytes());
    }
}

fn align_dword(out: &mut Vec<u8>) {
    out.resize(out.len().next_multiple_of(4), 0);
}
